<template>
<section v-if="role==='root'" class="panel mac-power-panel" aria-label="Mac自动唤醒与睡眠保护">
  <view class="section-head"><view><h2>唤醒与睡眠保护</h2><p class="hint">北京时间 · 接电、开盖、保持登录</p></view><button class="text-button" :disabled="busy" @click="$emit('refresh')">刷新</button></view>
  <view class="power-timeline"><view><strong>06:55</strong><text>唤醒</text></view><view><strong>07:00</strong><text>开抢</text></view><view><strong>07:05</strong><text>评估休眠</text></view></view>
  <view v-if="error||data?.install_error" class="notice error" role="alert">{{error||data.install_error}}</view>
  <p v-if="!data" class="hint">正在读取本机电源状态…</p>
  <template v-else>
    <view class="power-overview"><span>{{!data.installed?'未安装':!data.config.enabled?'未启用':data.config.paused?'已暂停':data.native_fresh?'已确认唤醒':'等待系统确认'}}</span><text>{{data.runner_fresh&&data.runner?.hold?'正在保护 · 启动器兜底':data.agent_fresh&&data.agent?.hold?'正在保护':data.agent_online&&data.runner_fresh?'已解除保护':'保护状态待确认'}}</text></view>
    <p class="next-wake">下次唤醒 <strong>{{data.config.enabled&&!data.config.paused&&data.installed&&data.native_fresh?time(data.native?.next_wake):'未确认'}}</strong></p>
    <p v-if="data.installed&&(!data.agent_online||!data.backend_fresh)" class="power-warning" role="status">{{!data.agent_online?'守护进程待恢复或未连接':'后台状态尚未更新或已过期'}}</p>
    <p v-if="data.native?.error" class="notice error">系统唤醒需检查：{{nativeError(data.native.error)}}</p>
    <button v-if="!data.installed" class="button" :disabled="busy||data.installing||!data.supported" @click="$emit('install')">{{data.installing?'请完成macOS授权…':'安装并启用系统唤醒'}}</button>
    <details class="power-settings"><summary>运行详情与设置</summary><view class="power-state"><view><text>系统组件</text><b>{{data.installed?'已安装':'未安装'}}</b></view><view><text>守护进程</text><b>{{data.agent_online?'已连接':'待恢复或未连接'}}</b></view><view><text>后台状态</text><b>{{data.backend_fresh?'已更新':'尚未更新或已过期'}}</b></view><view v-if="data.agent?.network?.checked_at"><text>校园网站</text><b>{{data.agent.network.ok?'可达':'待恢复'}}</b><small>{{time(data.agent.network.checked_at)}}</small></view></view><p v-if="data.agent?.reason" class="hint">{{data.agent_fresh?'':'上次状态（当前未确认）：'}}{{data.agent.reason}}</p><view v-if="data.installed" class="power-actions"><button class="button secondary" :disabled="busy||data.installing" @click="$emit('update',{enabled:!data.config.enabled,paused:false})">{{data.config.enabled?'关闭自动唤醒':'启用自动唤醒'}}</button><button v-if="data.config.enabled" class="button secondary" :disabled="busy||data.installing" @click="$emit('update',{paused:!data.config.paused})">{{data.config.paused?'恢复守护':'暂停守护'}}</button><button class="button ghost" :disabled="busy||data.installing" @click="$emit('install')">修复安装</button></view></details>
    <p v-if="data.installing" class="hint">安装正在等待系统授权或核对读回结果，请保持本机登录。无需发送Mac密码。</p>
    <p v-if="!data.supported" class="hint">原生自动唤醒仅支持macOS执行电脑。</p>
  </template>
  <details class="power-limits"><summary>放置要求与休眠说明</summary><p>请接电、开盖放置，允许屏幕熄灭。普通合盖可能让Mac进入睡眠，无法保证按时联网预约；软件不会绕过系统的合盖或登录保护。</p><p v-if="data?.agent?.system">{{data.agent_fresh?'':'上次环境读回：'}}电源：{{data.agent.system.ac===true?'已接电':data.agent.system.ac===false?'未接电':'未确认'}} · 上盖：{{data.agent.system.lid_closed===true?'已合盖，有中断风险':data.agent.system.lid_closed===false?'已打开':'未确认'}}</p><p>07:05后仅在本轮任务结束、没有待核对任务且后台正常时释放保护。异常会显示原因并继续保护；不会强制休眠或关闭其他应用。</p><p>关闭或暂停此功能会保留预约计划和历史。停止软件时会暂停守护，手动重新启动时恢复。关机、退出Mac账户或开机尚未解锁不在自动恢复范围内。</p><p v-if="data?.agent?.system?.blockers?.length">当前系统断言持有者：{{data.agent.system.blockers.join('、')}}。系统设置及其他应用仍可能阻止休眠。</p></details>
</section>
</template>
<script setup>
defineProps({role:String,data:Object,error:String,busy:Boolean});
defineEmits(['refresh','install','update']);
const time=value=>Number.isFinite(value)&&value>0?new Date(value*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未确认';
const nativeError=value=>({config_invalid:'配置未能安全读取',schedule_read_failed:'无法读取电源事件',schedule_parse_failed:'电源事件格式异常',schedule_cancel_failed:'旧事件取消未确认',schedule_create_failed:'唤醒事件注册失败',schedule_readback_failed:'无法读回事件',schedule_not_confirmed:'唤醒事件尚未确认'}[value]||'请检查系统安装状态');
</script>
<style scoped>
.mac-power-panel{margin-top:28px;max-width:840px}.mac-power-panel .section-head{align-items:flex-start;gap:16px;margin-bottom:20px}.mac-power-panel .section-head .hint{font-size:12px}.power-timeline{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:20px}.power-timeline>view{display:flex;flex-direction:column;gap:4px;align-items:flex-start;min-width:0}.power-timeline strong{font-size:16px;font-weight:550}.power-timeline text{font-size:12px;color:var(--muted)}.power-overview{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:14px}.power-overview>span{color:var(--green);font-weight:550}.power-overview text{font-size:12px;color:var(--muted)}.next-wake{font-size:12px;color:var(--muted);margin:12px 0 18px}.next-wake strong{font-weight:500;color:var(--ink);margin-left:8px}.power-warning{font-size:13px;color:var(--amber);margin-bottom:16px}.power-settings,.power-limits{border-top:1px solid var(--line);font-size:13px}.power-settings summary,.power-limits summary{cursor:pointer;min-height:48px;display:flex;align-items:center;color:var(--muted)}.power-state{display:grid;grid-template-columns:1fr 1fr;gap:16px 24px;margin:12px 0 20px}.power-state>view{display:flex;flex-direction:column;gap:6px;min-width:0}.power-state text,.power-state small{font-size:12px;color:var(--muted)}.power-state b{font-size:13px;font-weight:500;overflow-wrap:anywhere}.power-actions{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.power-limits p{font-size:12px;line-height:1.8;color:var(--muted);margin:0 0 12px}.mac-power-panel>.notice{overflow-wrap:anywhere}@media(max-width:599px){.power-timeline{gap:12px}.power-timeline>view{flex-direction:column;gap:4px;flex:1}.power-timeline strong{font-size:16px}.power-timeline text{line-height:1.5}.power-state{gap:18px 14px}.power-actions{display:grid;grid-template-columns:1fr}.mac-power-panel .section-head h2{font-size:17px}}
.power-settings summary::after{content:"⌄";margin-left:auto;font-size:15px}.power-settings[open]>summary::after{transform:rotate(180deg)}.power-limits summary::after{content:"⌄";margin-left:auto;font-size:15px}.power-limits[open]>summary::after{transform:rotate(180deg)}
</style>
